        assertThat(millis, not(0L));
    }

    @Test
    public void testComputeMillisBooleanString_Reset() throws Exception{
        bucket.saveField(DateTimeFieldType.year(), 2020);
        long millis = bucket.computeMillis(true, null);
        assertThat(millis, not(0L));
    }

    @Test(expected = IllegalFieldValueException.class)
    public void testComputeMillisBooleanString_IllegalFieldValueException() throws Exception{
        bucket.saveField(DateTimeFieldType.year(), 2020);
        bucket.iSavedFields[0].iField = DateTimeFieldType.dayOfMonth();
