        when(field.add(1000, 1000)).thenReturn(2000L);
        when(base.getZone().convertLocalToUTC(2000, false, instant)).thenReturn(2000L);
        long result = lenientDateTimeField.set(instant, value);
        Assert.assertEquals(2000, result);
    }

