public class ImpreciseCutoverFieldTest{
private ImpreciseCutoverField impreciseCutoverField;
    private DateTimeField julianField;
    private DateTimeField gregorianField;
    private long cutoverMillis;

    @Before
    public void setUp(){
        julianField = Mockito.mock(DateTimeField.class);
        gregorianField = Mockito.mock(DateTimeField.class);
        cutoverMillis = System.currentTimeMillis();
        impreciseCutoverField = new ImpreciseCutoverField(julianField, gregorianField, cutoverMillis);
    }

    @Test
    public void testAdd_InstantBeforeCutover_AddsToJulian(){
        // Arrange
        long instant = cutoverMillis - 1000;
        int value = 1;
        Mockito.when(julianField.add(instant, value)).thenReturn(instant + 1000);

        // Act
        long result = impreciseCutoverField.add(instant, value);

        // Assert
        Assert.assertEquals(instant + 1000, result);
        Mockito.verify(julianField, Mockito.times(1)).add(instant, value);
        Mockito.verify(gregorianField, Mockito.never()).add(Mockito.anyLong(), Mockito.anyInt());
    }

    @Test
    public void testAdd_InstantBeforeCutover_AddsToJulian_CrossesCutover(){
        // Arrange
        long instant = cutoverMillis - 1000;
        int value = 2;
        long resultJulian = cutoverMillis + 1000;
        Mockito.when(julianField.add(instant, value)).thenReturn(resultJulian);
        Mockito.when(gregorianField.add(resultJulian, -1)).thenReturn(resultJulian);

        // Act
        long result = impreciseCutoverField.add(instant, value);

        // Assert
        Assert.assertEquals(resultJulian, result);
        Mockito.verify(julianField, Mockito.times(1)).add(instant, value);
        Mockito.verify(gregorianField, Mockito.times(1)).add(Mockito.anyLong(), Mockito.anyInt());
    }

